def compute(vars):
    average_current_maturities = (vars["v1"] + vars["v2"]) / 2
    return {
        "value": average_current_maturities,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "average_current_maturities": average_current_maturities,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
